<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\ValueObject\Accessor\UserWellcomeAtAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserWellcomeAtAccessor trait.
 *
 * Covers null default, string/VO assignment via withWellcomeAt,
 * getWellcomeAt/wellcomeAt accessors, and isWellcomeAtChanged with/without original.
 */
class UserWellcomeAtAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withWellcomeAt creates a new instance with the WellcomeAt set
     * from a string value, and getWellcomeAt returns the primitive string.
     */
    public function testWithWellcomeAtFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserWellcomeAtAccessorUnitTest();

        // Act
        $result = $holder->withWellcomeAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->getWellcomeAt());
    }
    /**
     * Asserts that withwellcomeAt has access to the value object
     * from a string value, and getWellcomeAt returns the primitive string.
     */
    public function testWithWellcomeAtFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserWellcomeAtAccessorUnitTest();

        // Act
        $result = $holder->withWellcomeAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->wellcomeAt()->value());
    }
    public function testChangedWellcomeAt(): void
    {
        // Arrange
        $holder = new ImplWithUserWellcomeAtAccessorUnitTest();
        $original = $holder->withWellcomeAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $same = $holder->withWellcomeAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $modified = $holder->withWellcomeAt((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')));

        // Act
        $unchanged = $holder->isWellcomeAtChanged();
        $withSame = $original->isWellcomeAtChanged($same);
        $withDiferent = $original->isWellcomeAtChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserWellcomeAtAccessorUnitTest
{
    use UserWellcomeAtAccessor;
}
